/**
 * Bounded, server-only HTTP transport for the OPTIONAL stock installation proof.
 * Do not modify the existing Supabase catalog query module here: it is part
 * of Tayar's separately pinned/generated BYO Edge runtime source.
 *
 * No network probing or user-selectable URLs. Only Supabase Management API
 * read-only queries to an already owner-bound projectRef are accepted.
 */
const endpoint = /^https:\/\/api\.supabase\.com\/v1\/projects\/[a-z]{20}\/database\/query\/read-only$/;
const maxBytes = 1_048_576;
const maxRequestBytes = 65_536;

export function createBoundedOwnedStockCatalogFetcher(fetcher: typeof fetch = fetch): typeof fetch {
  return async (input, init) => {
    if (typeof input !== 'string' || !endpoint.test(input) || init?.method !== 'POST'
      || init.redirect !== 'error' || init.cache !== 'no-store'
      || typeof init.body !== 'string' || init.body.length < 1 || init.body.length > maxRequestBytes) {
      throw new Error('Customer stock catalog request unavailable.');
    }
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 8_000);
    let reader: ReadableStreamDefaultReader<Uint8Array> | undefined;
    try {
      const response = await fetcher(input, { ...init, signal: controller.signal });
      const declared = response.headers.get('content-length');
      if (response.status !== 201 || !response.body
        || (declared !== null && (!/^\d+$/.test(declared) || Number(declared) > maxBytes))) throw new Error();
      reader = response.body.getReader();
      const chunks: Uint8Array[] = [];
      let count = 0;
      for (;;) {
        const result = await reader.read();
        if (result.done) break;
        count += result.value.byteLength;
        if (count > maxBytes) throw new Error();
        chunks.push(result.value);
      }
      const bytes = new Uint8Array(count);
      let offset = 0;
      for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.byteLength; }
      const decoded: unknown = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes));
      if (!Array.isArray(decoded)) throw new Error();
      return Response.json(decoded, { status: 201 });
    } catch {
      throw new Error('Customer stock catalog transport unavailable.');
    } finally {
      clearTimeout(timer);
      controller.abort();
      if (reader) { try { await reader.cancel(); } catch { /* Always sanitize cleanup errors. */ } }
    }
  };
}
